<?php
 namespace QQWorld\Framework\Mail; use Zend\Mime\Mime; use Zend\Mime\Part; class Message implements MailMessageInterface { private $zendMessage; private $messageType = self::TYPE_TEXT; public function __construct($charset = 'utf-8') { $this->zendMessage = new \Zend\Mail\Message(); $this->zendMessage->setEncoding($charset); } public function setMessageType($type) { $this->messageType = $type; return $this; } public function setBody($body) { if (is_string($body) && $this->messageType === MailMessageInterface::TYPE_HTML) { $body = self::createHtmlMimeFromString($body); } $this->zendMessage->setBody($body); return $this; } public function setSubject($subject) { $this->zendMessage->setSubject($subject); return $this; } public function getSubject() { return $this->zendMessage->getSubject(); } public function getBody() { return $this->zendMessage->getBody(); } public function setFrom($fromAddress) { $this->zendMessage->setFrom($fromAddress); return $this; } public function addTo($toAddress) { $this->zendMessage->addTo($toAddress); return $this; } public function addCc($ccAddress) { $this->zendMessage->addCc($ccAddress); return $this; } public function addBcc($bccAddress) { $this->zendMessage->addBcc($bccAddress); return $this; } public function setReplyTo($replyToAddress) { $this->zendMessage->setReplyTo($replyToAddress); return $this; } public function getRawMessage() { return $this->zendMessage->toString(); } private function createHtmlMimeFromString($htmlBody) { $htmlPart = new Part($htmlBody); $htmlPart->setCharset($this->zendMessage->getEncoding()); $htmlPart->setType(Mime::TYPE_HTML); $mimeMessage = new \Zend\Mime\Message(); $mimeMessage->addPart($htmlPart); return $mimeMessage; } public function setBodyHtml($html) { $this->setMessageType(self::TYPE_HTML); return $this->setBody($html); } public function setBodyText($text) { $this->setMessageType(self::TYPE_TEXT); return $this->setBody($text); } } 